local Fisherman = {}
local PRODUCTS = {
    herring_catch = { name = "Sled ulov", netCost = 1, baitCost = 1, time = 2, cost = 14, yield = 40, happiness = 1, description = "Sveže ulovljene sledi." },
    cod_catch = { name = "Bakalar ulov", netCost = 1, baitCost = 1, time = 3, cost = 25, yield = 50, prestige = 1, description = "Sveže ulovljen bakalar." },
    trout_catch = { name = "Postrv ulov", netCost = 1, baitCost = 1, time = 3, cost = 32, yield = 55, prestige = 2, description = "Sveže ulovljene postrvi." },
    salmon_catch = { name = "Losos ulov", netCost = 1, baitCost = 2, time = 5, cost = 75, yield = 65, prestige = 4, happiness = 1, description = "Sveže ulovljeni lososi." },
    silver_net_catch = { name = "Srebrno mrežni ulov", netCost = 1, silverCost = 1, baitCost = 2, time = 8, cost = 180, yield = 80, prestige = 10, happiness = 2, description = "Ulov s srebrno mrežo za plemiče." },
    royal_grand_catch = { name = "Kraljevski veliki ulov", netCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, baitCost = 3, time = 13, cost = 1000, yield = 100, prestige = 32, happiness = 7, description = "Veliki kraljevski ulov z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Ribarska postaja", cost = { gold = 220, wood = 120, stone = 150 }, upkeep = 5, qualityBonus = 5 },
    fishing_harbor = { name = "Ribje pristanišče", cost = { gold = 800, wood = 250, stone = 400, net = 10 }, upkeep = 20, qualityBonus = 18 },
    curing_house = { name = "Konzervirnica", cost = { gold = 2000, wood = 350, stone = 600, silver = 25, salt = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_fishing_atelier = { name = "Kraljevski atelje ribištva", cost = { gold = 8200, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 165, qualityBonus = 55, prestigeBonus = 40 },
}
Fisherman.netStock = 22; Fisherman.baitStock = 24; Fisherman.silverStock = 8; Fisherman.goldStock = 6; Fisherman.jewelStock = 6
Fisherman.productStock = {}; Fisherman.buildings = {}; Fisherman.maker = nil; Fisherman.activeMaking = {}; Fisherman.totalProducts = 0; Fisherman.dayTimer = 0
function Fisherman.init() Fisherman.netStock=22; Fisherman.baitStock=24; Fisherman.silverStock=8; Fisherman.goldStock=6; Fisherman.jewelStock=6; Fisherman.productStock={}; Fisherman.buildings={}; Fisherman.maker=nil; Fisherman.activeMaking={}; Fisherman.totalProducts=0; Fisherman.dayTimer=0; print("[Fisherman] Royal Fisherman System initialized (6 products, 4 buildings)") end
function Fisherman.hireMaker(n,s) s=s or math.random(45,85); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Fisherman.maker={name=n or ("Ribič "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ribič najet: %s (spretnost: %d)",Fisherman.maker.name,s),"success") end; return true end
function Fisherman.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Fisherman.build(id) local ok,e=Fisherman.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Fisherman.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Fisherman.getQualityBonus() local b=0; for _,bd in ipairs(Fisherman.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Fisherman.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.netCost and Fisherman.netStock<(d.netCost or 0) then return false,"Premalo mrež" end; if d.baitCost and Fisherman.baitStock<(d.baitCost or 0) then return false,"Premalo vabe" end; if d.silverCost and Fisherman.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and Fisherman.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and Fisherman.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #Fisherman.buildings==0 then return false,"Potrebna delavnica" end; if not Fisherman.maker then return false,"Potreben ribič" end; return true end
function Fisherman.make(pt,qty) qty=qty or 5; local ok,e=Fisherman.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.netCost then Fisherman.netStock=Fisherman.netStock-d.netCost*qty end; if d.baitCost then Fisherman.baitStock=Fisherman.baitStock-d.baitCost*qty end; if d.silverCost then Fisherman.silverStock=Fisherman.silverStock-d.silverCost*qty end; if d.goldCost then Fisherman.goldStock=Fisherman.goldStock-d.goldCost*qty end; if d.jewelCost then Fisherman.jewelStock=Fisherman.jewelStock-d.jewelCost*qty end; local t=d.time; if Fisherman.maker then t=math.max(1,t-math.floor(Fisherman.maker.skill/12)) end; table.insert(Fisherman.activeMaking,{id="fish_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function Fisherman.completeMaking(m) local q=1.0+(Fisherman.getQualityBonus()/100); if Fisherman.maker then q=q+(Fisherman.maker.skill/180) end; q=math.min(2.0,q); Fisherman.productStock[m.productType]=(Fisherman.productStock[m.productType] or 0)+m.quantity; Fisherman.totalProducts=Fisherman.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if Fisherman.maker then Fisherman.maker.itemsMade=Fisherman.maker.itemsMade+m.quantity; if math.random()<0.20 then Fisherman.maker.skill=math.min(100,Fisherman.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ribe ulovljene: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fish.completed",{productName=m.productName,yield=m.yield,happiness=m.happiness}) end end
function Fisherman.update(dt) if not _G.state then return end; Fisherman.dayTimer=Fisherman.dayTimer+dt; if Fisherman.dayTimer>=30 then Fisherman.dayTimer=0; for i=#Fisherman.activeMaking,1,-1 do local m=Fisherman.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Fisherman.completeMaking(m); table.remove(Fisherman.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Fisherman.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Fisherman.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Fisherman.getStats() return {netStock=Fisherman.netStock,baitStock=Fisherman.baitStock,silverStock=Fisherman.silverStock,goldStock=Fisherman.goldStock,jewelStock=Fisherman.jewelStock,productStock=Fisherman.productStock,numBuildings=#Fisherman.buildings,hasMaker=Fisherman.maker~=nil,makerName=Fisherman.maker and Fisherman.maker.name or "—",makerSkill=Fisherman.maker and Fisherman.maker.skill or 0,activeMaking=#Fisherman.activeMaking,totalProducts=Fisherman.totalProducts} end
return Fisherman
